import static dev.astralreach.hytale.RocketRegistry.Cell;

/** Paid, normally saved player-built orbital outposts. The existing journey remains the travel authority. */
final class StationService {
 private static final Set<UUID>pending=ConcurrentHashMap.newKeySet();
 static StationRegistry data(Store<EntityStore>s){return s.getResource(AstralReachPlugin.stationType);}
 static Cell cell(StationLayout.Cell c){return new Cell(c.x(),c.y(),c.z());}
 static boolean world(Store<EntityStore>s){return s.getExternalData().getWorld().getName().equals(SpaceFlight.ORBIT_WORLD);}
 static PlayerFlightState paid(Store<EntityStore>s,Ref<EntityStore>r){var f=s.getComponent(r,AstralReachPlugin.flightType);if(!world(s)||f==null||f.trip==null||f.trip.phase()!=Journey.Phase.ORBIT||f.leg!=PlayerFlightState.Leg.NONE||RocketService.transferring.contains(s.getComponent(r,PlayerRef.getComponentType()).getUuid()))throw new IllegalArgumentException("Reach orbit on a funded flight before using stations.");return f;}
 static StationRegistry.Station docked(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p){var f=paid(s,r);var st=f.stationOwner==null?null:data(s).stations.get(f.stationOwner);if(st==null||!st.allows(p.getUuid()))throw new IllegalArgumentException("You are not docked at an authorised station.");return st;}
 static List<StationRegistry.Station>available(Store<EntityStore>s,UUID p){return data(s).stations.values().stream().filter(st->st.allows(p)).sorted(Comparator.comparing((StationRegistry.Station st)->!st.owner.equals(p)).thenComparing(st->st.name,String.CASE_INSENSITIVE_ORDER)).toList();}
 static int cores(Store<EntityStore>s,Ref<EntityStore>r){var p=s.getComponent(r,Player.getComponentType());int n=0;if(p!=null){var inv=p.getInventory().getCombinedStorageHotbarBackpack();for(short i=0;i<inv.getCapacity();i++){var item=inv.getItemStack(i);if(!ItemStack.isEmpty(item)&&item.getItemId().equals("AR_StationCore"))n+=item.getQuantity();}}return n;}
 static void open(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p){try{paid(s,r);if(StationDocks.inTransit(p.getUuid()))throw new IllegalArgumentException("Wait for the docking sequence to finish.");StationPage.open(s,r,p);}catch(IllegalArgumentException e){AstralReachPlugin.message(p,e.getMessage());}}
 static void use(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,Cell at){try{var st=docked(s,r,p);var root=NativeBlocks.root(s.getExternalData().getWorld(),at);if(root==null)root=at;if(!cell(st.layout.core()).equals(root)&&StationStructure.portAt(st,root)<0||!RocketService.near(s,r,root))throw new IllegalArgumentException("Stand beside the station Core or an airlock terminal.");open(s,r,p);}catch(IllegalArgumentException e){AstralReachPlugin.message(p,e.getMessage());}}
 static void deploy(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p){try{
  var f=paid(s,r);if(!SpaceFlight.inOrbit(s,r))throw new IllegalArgumentException("Deploy a core from orbital navigation.");if(data(s).stations.containsKey(p.getUuid()))throw new IllegalArgumentException("Your station is already deployed.");ExpeditionSuit.require(s,r,1);OxygenService.requireDeparture(s,r);if(cores(s,r)<1)throw new IllegalArgumentException("Carry one crafted Station Core. It includes the starter structure and empty diffuser.");if(!pending.add(p.getUuid()))return;
  int index=data(s).nextIndex;if(index>=StationLayout.MAX_PLOTS){pending.remove(p.getUuid());throw new IllegalArgumentException("The orbital station registry is full.");}data(s).nextIndex++;var layout=new StationLayout(index);var w=s.getExternalData().getWorld();
  StationStructure.load(w,layout.seed()).whenComplete((v,error)->w.execute(()->{
   pending.remove(p.getUuid());if(!r.isValid()||r.getStore()!=s||f.trip==null||!SpaceFlight.inOrbit(s,r)||data(s).stations.containsKey(p.getUuid()))return;
   if(error!=null){AstralReachPlugin.message(p,"Station plot could not load. Your Core remains in your inventory.");return;}
   var changes=new ArrayList<StationLayout.Part>();List<ItemStack>escrow=List.of();var inv=s.getComponent(r,Player.getComponentType()).getInventory().getCombinedStorageHotbarBackpack();
   try{paid(s,r);ExpeditionSuit.require(s,r,1);OxygenService.requireDeparture(s,r);var seed=layout.seed();for(var part:seed)if(!NativeBlocks.empty(w,cell(part.at()))||BlockType.getAssetMap().getAsset(part.item())==null)throw new IllegalArgumentException("Station plot is obstructed or its assets are unavailable; no Core spent.");
    escrow=YardInventory.take(inv,Map.of("AR_StationCore",1));if(escrow.size()!=1||escrow.getFirst().getQuantity()!=1)throw new IllegalArgumentException("Carry one Station Core before deployment.");
    for(var part:seed){if(!StationStructure.put(w,part))throw new IllegalStateException("Station placement could not finish");changes.add(part);}
    var st=new StationRegistry.Station(p.getUuid(),p.getUsername(),index);st.shellVersion=2;data(s).stations.put(st.owner,st);OxygenService.data(s).diffusers.put(cell(layout.diffuser()),new OxygenRegistry.Diffuser(p.getUuid()));
    StationDocks.dock(s,r,p,st);AstralReachPlugin.message(p,"Station deployed with nine protected airlocks. Build from the three small platforms inside your193×193 area; fill the included oxygen diffuser.");
   }catch(RuntimeException ex){if(!data(s).stations.containsKey(p.getUuid())){for(var part:changes)if(NativeBlocks.base(NativeBlocks.get(w,cell(part.at()))).equals(part.item()))NativeBlocks.set(w,cell(part.at()),BlockType.getAssetMap().getAsset("Empty"));if(!YardInventory.refund(inv,escrow))throw new IllegalStateException("Station rollback could not restore its exact Core",ex);}AstralReachPlugin.message(p,"Station deployment paused: "+ex.getMessage());}
  }));
 }catch(IllegalArgumentException ex){AstralReachPlugin.message(p,ex.getMessage());}}
 static void dock(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,UUID owner){try{var f=paid(s,r);if(!SpaceFlight.inOrbit(s,r))throw new IllegalArgumentException("Choose a station from orbital navigation.");var st=data(s).stations.get(owner);if(st==null||!st.allows(p.getUuid()))throw new IllegalArgumentException("The owner must invite you before you can dock.");ExpeditionSuit.require(s,r,1);OxygenService.requireDeparture(s,r);if(!pending.add(p.getUuid()))return;var w=s.getExternalData().getWorld();StationStructure.load(w,st.layout.shell()).whenComplete((v,error)->w.execute(()->{pending.remove(p.getUuid());if(!r.isValid()||r.getStore()!=s||f.trip==null||!SpaceFlight.inOrbit(s,r))return;try{paid(s,r);if(error!=null||data(s).stations.get(owner)!=st||!st.allows(p.getUuid()))throw new IllegalArgumentException("Station access or loading changed. Your return reserve is retained.");ExpeditionSuit.require(s,r,1);OxygenService.requireDeparture(s,r);StationDocks.dock(s,r,p,st);}catch(IllegalArgumentException ex){AstralReachPlugin.message(p,ex.getMessage());}}));}catch(IllegalArgumentException ex){AstralReachPlugin.message(p,ex.getMessage());}}
 static void undock(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p){leave(s,r,p,false);}
 static void returnFromStation(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p){leave(s,r,p,true);}
 private static void leave(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,boolean home){try{var f=paid(s,r);if(StationDocks.inTransit(p.getUuid()))throw new IllegalArgumentException("Wait for the docking sequence to finish.");if(f.stationOwner==null)throw new IllegalArgumentException("You are already in orbital navigation.");if(!pending.add(p.getUuid()))return;var w=s.getExternalData().getWorld();SpaceFlight.orbitLanding(p).whenComplete((dest,error)->w.execute(()->{pending.remove(p.getUuid());if(!r.isValid()||r.getStore()!=s||f.trip==null||f.stationOwner==null)return;if(error!=null){AstralReachPlugin.message(p,"Orbital departure is blocked. Your return reserve is retained.");return;}StationDocks.depart(s,r,p,home,dest);}));}catch(IllegalArgumentException ex){AstralReachPlugin.message(p,ex.getMessage());}}
 static void invite(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,String name){var st=docked(s,r,p);if(!st.owner.equals(p.getUuid()))throw new IllegalArgumentException("Only the station owner can invite builders.");var target=Universe.get().getPlayers().stream().filter(q->q.getUsername().equalsIgnoreCase(name.strip())).findFirst().orElseThrow(()->new IllegalArgumentException("Enter an online player's exact name."));if(st.owner.equals(target.getUuid())||st.crew.containsKey(target.getUuid()))throw new IllegalArgumentException("That player already has access.");if(st.crew.size()>=StationLayout.MAX_CREW)throw new IllegalArgumentException("This station already has eight invited builders.");st.crew.put(target.getUuid(),target.getUsername());RocketService.cue(s,p,"AR_Blueprint_Lock",cell(st.layout.core()));}
 static void revoke(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,UUID guest){var st=docked(s,r,p);if(!st.owner.equals(p.getUuid()))throw new IllegalArgumentException("Only the station owner can change the crew.");st.crew.remove(guest);st.moorings.remove(guest);}
 static void tick(Store<EntityStore>s){if(!world(s))return;var w=s.getExternalData().getWorld();if(!"AR_StationOrbit".equals(w.getWorldConfig().getForcedWeather())){w.getWorldConfig().setForcedWeather("AR_StationOrbit");w.getWorldConfig().markChanged();s.getResource(com.hypixel.hytale.builtin.weather.resources.WeatherResource.getResourceType()).setForcedWeather("AR_StationOrbit");}
  OrbitEnvironment.tick(s);
  for(var st:data(s).stations.values())StationStructure.ensure(s,st);
  StationSkyCatalog.publish(data(s));
  StationDocks.tick(s);
  for(var p:w.getPlayerRefs()){var r=p.getReference();if(r==null||!r.isValid()||r.getStore()!=s)continue;var player=s.getComponent(r,Player.getComponentType());if(player!=null&&player.getPageManager().getCustomPage() instanceof StationPage page)page.refresh(s,r);var f=s.getComponent(r,AstralReachPlugin.flightType);if(f==null||f.trip==null||f.stationOwner==null||f.trip.phase()!=Journey.Phase.ORBIT||RocketService.transferring.contains(p.getUuid())||StationDocks.inTransit(p.getUuid()))continue;var st=data(s).stations.get(f.stationOwner);if(st==null||!st.allows(p.getUuid())){undock(s,r,p);continue;}if(st.shellVersion==2)StationDocks.recover(s,r,p,st);var at=s.getComponent(r,TransformComponent.getComponentType()).getPosition();if(!st.layout.walkingContains(at.x,at.y,at.z)){if(st.shellVersion==2){f.boarded=true;StationDocks.recover(s,r,p,st);}else{var a=st.layout.arrival();if(RocketService.safe(w,a.x()+.5,a.y(),a.z()+.5))RocketService.teleport(s,r,p,w,new Transform(a.x()+.5,a.y(),a.z()+.5),()->{});else undock(s,r,p);}}}
 }
 private static String refusal(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,Cell at,boolean placing){if(!world(s))return null;var f=s.getComponent(r,AstralReachPlugin.flightType);var st=f==null||f.stationOwner==null?null:data(s).stations.get(f.stationOwner);if(st==null||f.trip==null||f.trip.phase()!=Journey.Phase.ORBIT||!st.allows(p.getUuid())||!st.layout.contains(at.x(),at.y(),at.z()))return "Build only inside a station plot where you are an invited builder.";if(cell(st.layout.core()).equals(at)||st.layout.arrivalSpace(new StationLayout.Cell(at.x(),at.y(),at.z())))return "Keep the permanent station core and marked arrival square clear.";return null;}
 static final class Placement extends EntityEventSystem<EntityStore,PlaceBlockEvent>{Placement(){super(PlaceBlockEvent.class);}@Override public Query<EntityStore>getQuery(){return PlayerRef.getComponentType();}@Override public void handle(int i,ArchetypeChunk<EntityStore>c,Store<EntityStore>s,CommandBuffer<EntityStore>b,PlaceBlockEvent e){if(e.isCancelled())return;var p=c.getComponent(i,PlayerRef.getComponentType());var pos=e.getTargetBlock();String reason=refusal(s,c.getReferenceTo(i),p,new Cell(pos.x,pos.y,pos.z),true);if(e.getItemInHand()!=null&&Set.of("AR_StationCore","AR_StationConcourse","AR_StationAirlock").contains(e.getItemInHand().getItemId()))reason="Deploy the Station Core from Orbis Stations after reaching orbit.";if(reason!=null){e.setCancelled(true);AstralReachPlugin.message(p,reason);}}}
 static final class Breaking extends EntityEventSystem<EntityStore,BreakBlockEvent>{Breaking(){super(BreakBlockEvent.class);}@Override public Query<EntityStore>getQuery(){return PlayerRef.getComponentType();}@Override public void handle(int i,ArchetypeChunk<EntityStore>c,Store<EntityStore>s,CommandBuffer<EntityStore>b,BreakBlockEvent e){if(e.isCancelled())return;var p=c.getComponent(i,PlayerRef.getComponentType());var pos=e.getTargetBlock();String reason=refusal(s,c.getReferenceTo(i),p,new Cell(pos.x,pos.y,pos.z),false);if(reason!=null){e.setCancelled(true);AstralReachPlugin.message(p,reason);}}}
 static final class Damage extends EntityEventSystem<EntityStore,DamageBlockEvent>{Damage(){super(DamageBlockEvent.class);}@Override public Query<EntityStore>getQuery(){return PlayerRef.getComponentType();}@Override public void handle(int i,ArchetypeChunk<EntityStore>c,Store<EntityStore>s,CommandBuffer<EntityStore>b,DamageBlockEvent e){if(e.isCancelled())return;var p=c.getComponent(i,PlayerRef.getComponentType());var pos=e.getTargetBlock();if(refusal(s,c.getReferenceTo(i),p,new Cell(pos.x,pos.y,pos.z),false)!=null)e.setCancelled(true);}}
}
